class Order {
  items: { price: number; qty: number }[];
  constructor(items: any[]) { this.items = items; }
}

class Customer {
  orders: Order[];
  loyaltyPoints: number;
  totalOrderAmount(order: Order) { return order.items.reduce((s, i) => s + i.price * i.qty, 0); }
}

class Invoice {
  items: { price: number; qty: number }[];
  customer: { loyaltyPoints: number };
  constructor(items: any[], customer: any) { this.items = items; this.customer = customer; }
  applyCustomerDiscount() {
    if (this.customer.loyaltyPoints > 100) return this.total() * 0.9;
    return this.total();
  }
  total() { return this.items.reduce((s, i) => s + i.price * i.qty, 0); }
}

// Version A
class ShoppingCart {
  items: { product: Product; qty: number }[];
  totalWeight() { return this.items.reduce((w, it) => w + it.product.weight * it.qty, 0); }
}

// Version B
class Product {
  weight: number;
  weightForQuantity(qty: number) { return this.weight * qty; }
}
class ShoppingCartB {
  items: { product: Product; qty: number }[];
  totalWeight() { return this.items.reduce((w, it) => w + it.product.weightForQuantity(it.qty), 0); }
}
